import{_ as a,a as t,c as l,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 80 The Crystal Palace","description":"学习 被动语态与信息重点，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 80 The Crystal Palace","description":"学习 被动语态与信息重点，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 被动语态与信息重点，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 79 By air","link":"/life/english/new-concept/book-2/unit-04/lesson-079"},"next":{"text":"第二册：实践与进步 · Lesson 81 Escape","link":"/life/english/new-concept/book-2/unit-04/lesson-081"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 79 By air","link":"/life/english/new-concept/book-2/unit-04/lesson-079"},"next":{"text":"第二册：实践与进步 · Lesson 81 Escape","link":"/life/english/new-concept/book-2/unit-04/lesson-081"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-04/lesson-080.md","filePath":"life/english/new-concept/book-2/unit-04/lesson-080.md"}'),i={name:"life/english/new-concept/book-2/unit-04/lesson-080.md"};function s(o,e,r,d,h,c){return t(),l("div",null,[...e[0]||(e[0]=[n('<h1 id="第二册-实践与进步-·-lesson-80-the-crystal-palace" tabindex="-1">第二册：实践与进步 · Lesson 80 The Crystal Palace <a class="header-anchor" href="#第二册-实践与进步-·-lesson-80-the-crystal-palace" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 80 The Crystal Palace&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元 4</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>大型展馆的建筑材料和迁移历史可用被动清楚呈现；练习历史叙述中的被动与定语。本课的语言观察是：was built 表一次建造事实，was later moved 表后来的移动。先后可用 later 明示，不一定每个先发生的动作都要过去完成时。完成学习后，请为虚构展馆写三句简介，说明建材、原用途和现在的遗存。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>exhibition</td><td>/ˌeksɪˈbɪʃən/</td><td>n.</td><td>展览</td><td>an international exhibition</td></tr><tr><td>palace</td><td>/ˈpæləs/</td><td>n.</td><td>宫殿</td><td>a royal palace</td></tr><tr><td>glass</td><td>/ɡlɑːs/</td><td>n.</td><td>玻璃</td><td>a sheet of glass</td></tr><tr><td>structure</td><td>/ˈstrʌktʃə/</td><td>n.</td><td>结构</td><td>a steel structure</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>be used for — 被用来，for 后接名词或动名词</li><li>on display — 在展出，不加冠词</li></ul><h2 id="语法讲解-被动语态与信息重点" tabindex="-1">语法讲解：被动语态与信息重点 <a class="header-anchor" href="#语法讲解-被动语态与信息重点" aria-label="Permalink to &quot;语法讲解：被动语态与信息重点&quot;">​</a></h2><p>被动语态由相应时态的 be 加过去分词构成，把动作的承受者放在主语位置。时态变化主要体现在 be 上，过去分词本身不随主语改变。只有可以带宾语的相关用法才能形成通常的被动句，happen、arrive 等不及物动词不能照搬。执行者未知、不重要或已经显然时可以省略 by 短语；需要追责或形成对比时则应保留。本课应用：was built 表一次建造事实，was later moved 表后来的移动。先后可用 later 明示，不一定每个先发生的动作都要过去完成时。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The exhibition hall was built from glass and steel.</p></blockquote><p>这座展厅是用玻璃和钢建造的。</p><p>was built 为一般过去被动，from glass and steel 说明建材；主语是展厅而非建造者。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>was build 错误，build 的过去分词是 built。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>比较 built 的 /lt/ 与 glass 的 /s/，将 glass and steel 连成建材语块。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The exhibition hall was built from glass and steel. After the exhibition, parts of it were reused. A small section now stands in a public garden.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>为虚构展馆写三句简介，说明建材、原用途和现在的遗存。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：was built 为一般过去被动，from glass and steel 说明建材；主语是展厅而非建造者。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：was build 错误，build 的过去分词是 built。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 build 的过去分词：The hall was ___ in one year.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> built</p><p><strong>解析：</strong> build 的过去式和过去分词均为 built。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>现在公园里保留了整个展厅吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> No, only a small section.</p><p><strong>解析：</strong> parts 与 a small section 限定保留范围。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>把 They reused parts of the hall 改为被动句。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Parts of the hall were reused.</p><p><strong>解析：</strong> parts 为复数，过去被动用 were。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：被动语态与信息重点。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-079">上一课</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-04/lesson-081">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(i,[["render",s]]);export{u as __pageData,b as default};
